import { retrieveOutcomes, retrieveTechniques } from './retrieval.mjs';
import { rerankTechniques } from './reranker.mjs';
import { composeTechniqueDag } from './composer.mjs';
import { freezeRoutePlan } from './route-plan.mjs';
function sections(operation){if(operation==='verification')return['overview','verification','failure-modes'];if(operation==='novel')return['overview','procedure','examples'];if(operation==='planning')return['overview','procedure','decision-tables'];return['overview','procedure'];}
export function routeSkillIntelligence({graph,providers,intent,context={}}){if(!graph||!intent?.query)throw new TypeError('graph and intent.query are required');const outcomeCandidates=retrieveOutcomes(graph,intent,{limit:16});const techniqueCandidates=retrieveTechniques(graph,outcomeCandidates,intent,{limit:32});const ranked=rerankTechniques(graph,techniqueCandidates,intent,context,providers??[]);const explicit=intent.targetOutcomeIds??[];const maxOutcomes=Math.max(1,Number(intent.maxOutcomes??1));const domainSet=new Set(intent.domains??[]);const rankedTargets=[];for(const inclusion of ranked.inclusions){const ordered=[...inclusion.mappedOutcomes].sort((a,b)=>{const ao=graph.outcomes.find((item)=>item.outcomeId===a),bo=graph.outcomes.find((item)=>item.outcomeId===b);return Number(domainSet.has(bo?.domain))-Number(domainSet.has(ao?.domain))||a.localeCompare(b);});for(const target of ordered)if(!rankedTargets.includes(target))rankedTargets.push(target);}const targets=explicit.length?explicit:(rankedTargets.length?rankedTargets.slice(0,maxOutcomes):outcomeCandidates.slice(0,maxOutcomes).map((item)=>item.outcome.outcomeId));const composed=composeTechniqueDag(graph,ranked.inclusions,targets);const selectedSections=sections(context.operation);const steps=composed.steps.map((step)=>({...step,sections:selectedSections,evidenceObligations:graph.outcomes.filter((outcome)=>step.outcomeIds.includes(outcome.outcomeId)).flatMap((outcome)=>outcome.evidence??[])}));const blockers=[];for(const target of targets)if(!steps.some((step)=>step.outcomeIds.includes(target)))blockers.push(`No executable stable technique/provider path for ${target}`);if(!steps.length)blockers.push('No executable technique/provider route was found');const tokenEstimate=steps.reduce((sum,step)=>{const provider=(providers??[]).find((item)=>item.providerId===step.providerId);return sum+(provider?.estimatedTokens??0);},0);const selectedTechniqueIds=new Set(steps.map((step)=>step.techniqueId));const nonSelected=ranked.inclusions.filter((item)=>!selectedTechniqueIds.has(item.id)).map((item)=>({id:item.id,reasons:[...item.reasons,'not-selected: lower rank or outside the minimal outcome closure'],providerId:item.provider.providerId}));return freezeRoutePlan({schemaVersion:2,intent:{query:intent.query,domains:[...(intent.domains??[])],taskClass:intent.taskClass??'generic',targetOutcomeIds:targets},context:{model:context.model??'generic',assurance:context.assurance??'A1',tools:[...(context.tools??[])],operation:context.operation??'routine'},outcomes:outcomeCandidates.map((item)=>({outcomeId:item.outcome.outcomeId,score:item.score,reasons:item.reasons})),steps,executionGroups:composed.executionGroups,inclusions:ranked.inclusions.map((item)=>({id:item.id,score:Number(item.score.toFixed(6)),providerId:item.provider.providerId,reasons:item.reasons})),exclusions:[...ranked.exclusions,...nonSelected],blockers,budget:{estimatedSkillTokens:tokenEstimate,selectedSections,withinRouteLimit:tokenEstimate<=Number(context.routeBudgetTokens??Number.MAX_SAFE_INTEGER)},stopConditions:[...new Set(steps.flatMap((step)=>step.outcomeIds.map((id)=>`${id} satisfied with current evidence`)))]});}
